{
  "results": [
    {
      "server": "solo",
      "tools": [
        {
          "tool_name": "solo__whoami",
          "description": "Show this MCP session's identified Solo process, session-scoped actor, and effective project scope. Pass an OS PID only as a fallback when the session is not already identified. Pass verbose=true for expanded tool hints.",
          "score": 6.002013683319092,
          "input_schema": {
            "$schema": "https://json-schema.org/draft/2020-12/schema",
            "title": "WhoAmIParams",
            "type": "object",
            "properties": {
              "pid": {
                "description": "Optional host OS PID fallback (from $$ in shell or os.getpid() in Python). Ignored once this MCP session is already identified as a Solo process.",
                "type": "integer",
                "format": "uint32",
                "minimum": 0
              },
              "verbose": {
                "description": "Include expanded MCP tool hints such as starter-tool names and spawning workflow text.",
                "type": "boolean"
              }
            }
          }
        },
        {
          "tool_name": "solo__list_projects",
          "description": "List Solo projects. Auto-select the project if there is only one.",
          "score": 0.1506049633026123,
          "input_schema": {
            "type": "object",
            "properties": {}
          }
        },
        {
          "tool_name": "solo__submit_solo_feedback",
          "description": "Open Solo's feedback form with a drafted bug, friction, or feature request.",
          "score": 0.14833150804042816,
          "input_schema": {
            "$schema": "https://json-schema.org/draft/2020-12/schema",
            "title": "SubmitSoloFeedbackParams",
            "type": "object",
            "properties": {
              "message": {
                "description": "Feedback about the Solo application itself. Include concrete bugs, friction, or feature requests.",
                "type": "string"
              },
              "email": {
                "description": "Optional email for follow-up from the Solo team.",
                "type": "string"
              },
              "include_context": {
                "description": "When true, append MCP session and process context to the submitted message. Defaults to true.",
                "type": "boolean",
                "default": true
              }
            },
            "required": [
              "message"
            ]
          }
        },
        {
          "tool_name": "solo__mcp_tools_summary",
          "description": "List enabled Solo MCP tools by category with one-line descriptions and no input schemas.",
