            "$schema": "https://json-schema.org/draft/2020-12/schema",
            "title": "WhoAmIParams",
            "type": "object",
            "properties": {
              "pid": {
                "description": "Optional host OS PID fallback (from $$ in shell or os.getpid() in Python). Ignored once this MCP session is already identified as a Solo process.",
                "type": "integer",
