          "score": 14.625635147094727,
          "input_schema": {
            "$schema": "https://json-schema.org/draft/2020-12/schema",
            "title": "ScratchpadReadParams",
            "type": "object",
            "properties": {
              "project_id": {
                "description": "Optional project scope override.",
                "type": "integer",
                "format": "int64"
              },
              "scratchpad_id": {
                "type": "integer",
                "format": "int64"
              },
              "offset": {
                "description": "Line offset to start reading from (0-indexed). Default: 0.",
                "type": "integer",
                "format": "uint",
                "minimum": 0
              },
              "limit": {
                "description": "Maximum number of lines to return. Default: all remaining lines.",
                "type": "integer",
                "format": "uint",
                "minimum": 0
              },
              "content_only": {
                "description": "When true, return raw content text and move revision/url details into `_meta`.",
                "type": "boolean",
                "default": false
              },
              "mode": {
                "description": "Read mode. `full` and `content` return the scratchpad body, `headings` returns a markdown heading outline, and `section` returns one markdown section.",
                "$ref": "#/$defs/ScratchpadReadMode"
              },
              "section_heading": {
                "description": "Required when `mode=section`. Matches a heading text from `mode=headings`; matching is whitespace-normalized and case-insensitive.",
                "type": "string"
              }
            },
            "required": [
              "scratchpad_id"
            ],
            "$defs": {
              "ScratchpadReadMode": {
