                "type": "integer",
                "format": "int64"
              },
              "scratchpad_id": {
                "type": "integer",
                "format": "int64"
              }
            },
            "required": [
              "scratchpad_id"
            ]
          }
        },
        {
          "tool_name": "solo__scratchpad_transfer",
          "description": "Move a scratchpad to another project at an expected revision.",
          "score": 8.00216293334961,
          "input_schema": {
            "$schema": "https://json-schema.org/draft/2020-12/schema",
            "title": "ScratchpadTransferParams",
