            $checked[] = $f;
            if (fileContains($f, $markerNeedle)) {
                $candidates[] = $dir;
            }
        }
    }

    if (count($candidates) !== 1) {
        return [
            'status' => count($candidates) === 0 ? 'missing' : 'ambiguous',
            'reason' => count($candidates) === 0 ? 'exact_marker_not_found' : 'duplicate_exact_markers',
            'checked' => array_slice($checked, 0, 20),
        ];
    }

    $dir = $candidates[0];
    $messages = extractGrokMessages($dir);
    $signalsFile = "{$dir}/signals.json";
    $signals = is_file($signalsFile) ? (json_decode((string) file_get_contents($signalsFile), true) ?: []) : [];
    // Honest telemetry: do not surface toolFailureCount or other unverified counters.
    $usage = [
        'context_tokens_used' => (int) ($signals['contextTokensUsed'] ?? 0),
        'context_window_tokens' => (int) ($signals['contextWindowTokens'] ?? 0),
        'tool_call_count' => (int) ($signals['toolCallCount'] ?? 0),
        'session_duration_seconds' => (int) ($signals['sessionDurationSeconds'] ?? 0),
    ];

    $messagesJsonl = implode("\n", array_map(fn($m) => json_encode($m, JSON_UNESCAPED_SLASHES), $messages));

    $raw = [];
    foreach (['chat_history.jsonl','events.jsonl','updates.jsonl','signals.json','summary.json','prompt_context.json','resources_state.json','system_prompt.txt','terminal.log'] as $rf) {
        $p = "{$dir}/{$rf}";
        if (is_file($p)) {
            $raw[] = ['path' => $p, 'archive_name' => $rf];
        }
    }

