function hasAnyManifestUnder(string $dir): bool
{
    if (!is_dir($dir)) {
        return false;
    }
    $it = new RecursiveIteratorIterator(
        new RecursiveDirectoryIterator($dir, RecursiveDirectoryIterator::SKIP_DOTS),
        RecursiveIteratorIterator::LEAVES_ONLY,
    );
    foreach ($it as $f) {
        if ($f->getFilename() === 'manifest.json') {
            return true;
        }
    }
    return false;
}

/**
 * @return list<array<string, mixed>>
 */
function summarizeStagedAgentSessions(string $stagedDir): array
{
    $out = [];
    if (!is_dir($stagedDir)) {
        return $out;
    }
    // Walk provider/slug/manifest.json
    foreach (glob("{$stagedDir}/*/manifest.json") ?: [] as $mf) {
        $provider = basename(dirname($mf));
        $slugDir = dirname($mf);
        $slug = basename($slugDir);
        $m = json_decode((string) file_get_contents($mf), true) ?: [];
        $out[] = [
            'agent' => $provider,
            'slug' => $slug,
            'status' => $m['status'] ?? 'unknown',
            'solo_process_id' => $m['solo_process_id'] ?? null,
            'staged' => true,
        ];
    }
    return $out;
}

