        $stmt = $db->prepare('INSERT INTO processes (id, project_id, name, command, working_dir, kind) VALUES (?, 4, ?, ?, ?, ?)');
        $stmt->execute([$soloProcessId, 'child-worker', 'codex', $cwd, 'agent']);

