            'marker_match' => 'exact',
        ], JSON_THROW_ON_ERROR).PHP_EOL);
        file_put_contents("{$stagedProvider}/usage.json", json_encode(['input_tokens' => 11, 'output_tokens' => 3], JSON_THROW_ON_ERROR).PHP_EOL);
        file_put_contents("{$stagedProvider}/messages.jsonl", json_encode(['role' => 'user', 'content' => 'staged marker content']).PHP_EOL);
        mkdir("{$stagedProvider}/raw", recursive: true);
        file_put_contents("{$stagedProvider}/raw/rollout.jsonl", "{}\n");

        // Also put a minimal loop.md referencing a process so discovery doesn't warn hard
