/**
 * Returns problem string if the packet names lanes and the matching archive has zero healthy captures without waiver.
 * Does not check archive existence (caller decides).
 */
function capture_health_problem(string $root, string $branch): ?string
{
    $sessionsDirectory = $root.'/.orbit/sessions';
    $slug = archive_slug($branch);

    if (! is_dir($sessionsDirectory)) {
        return null; // no archive yet; existence handled elsewhere for cleanup
    }

    $candidates = [];
    foreach (new DirectoryIterator($sessionsDirectory) as $entry) {
        if ($entry->isDot() || ! $entry->isDir()) {
            continue;
        }
        $name = $entry->getFilename();
        if (preg_match('/^\d{4}-\d{2}-\d{2}-\d{6}-'.preg_quote($slug, '/').'$/', $name) === 1) {
            $candidates[] = $entry->getPathname();
        }
    }

    foreach ($candidates as $candidate) {
        $loopPath = $candidate.'/loop.md';
        $manifestPath = $candidate.'/agent-sessions/manifest.json';
        if (!is_file($loopPath) || !is_file($manifestPath)) {
            continue;
        }

        $loopContent = (string) file_get_contents($loopPath);
        $hasCaptureConcern = (bool) preg_match('/Agent session capture waivers|Worker:.*Solo process|Reviewer:.*Solo process/i', $loopContent);
        if (!$hasCaptureConcern) {
            continue;
        }

        $manifest = json_decode((string) file_get_contents($manifestPath), true) ?: [];
        $healthy = 0;
        if (isset($manifest['sessions']) && is_array($manifest['sessions'])) {
            foreach ($manifest['sessions'] as $s) {
                if (($s['status'] ?? '') === 'ok') {
                    $healthy++;
                }
            }
        }
        if ($healthy === 0 && isset($manifest['providers']) && is_array($manifest['providers'])) {
            foreach ($manifest['providers'] as $p) {
                if (is_array($p) && isset($p['ok']) && $p['ok'] > 0) {
                    $healthy = 1;
                    break;
                }
            }
        }

        if ($healthy === 0) {
            $hasWaiver = false;
            if (preg_match('/^-\s*Agent session capture waivers:\s*(.+)$/im', $loopContent, $m)) {
                $waiverVal = strtolower(trim($m[1]));
                if ($waiverVal !== '' && $waiverVal !== 'none') {
                    $hasWaiver = true;
                }
            }
            if (!$hasWaiver) {
                return 'zero healthy agent session captures for named lanes (worker/reviewer/analyzer) and no explicit waiver row; add captures or waiver label naming providers';
            }
        }
    }

    return null;
}

