/**
 * Returns true if the given agent-sessions dir contains staged provider captures
 * (provider sub-directories with manifest or other session artifacts).
 * Used to decide whether to skip live fallback extraction.
 */
function hasStagedCaptures(string $dir): bool
{
    if (!is_dir($dir)) {
        return false;
    }
    $entries = glob($dir . '/*', GLOB_ONLYDIR) ?: [];
    foreach ($entries as $providerDir) {
        if (is_file($providerDir . '/manifest.json')) {
            return true;
        }
        if (count(glob($providerDir . '/*') ?: []) > 0) {
            return true;
        }
    }
    return false;
}

